ALTER TABLE incoming_match_evaluation
    ADD COLUMN evaluation_revision text,
    ADD COLUMN evaluation_evidence jsonb NOT NULL DEFAULT '{}'::jsonb
        CHECK (jsonb_typeof(evaluation_evidence) = 'object');

-- Give already-persisted evaluations an opaque compare token without changing
-- their candidate evidence or policy. New tokens are generated by the service.
UPDATE incoming_match_evaluation
SET evaluation_revision = md5(group_id::text || evaluated_at::text)
WHERE evaluation_revision IS NULL;
